import { Router } from 'express';
import { requireUser } from '../middleware/auth.js';
import { config } from '../config.js';
import { verifyTransaction } from '../services/blockchain.js';
import {
  DEPOSIT_AUTOMATIC_CREDIT_READY,
  DEPOSIT_CHAIN_VERIFICATION_READY,
  DEPOSIT_CUSTOMER_INTAKE_READY,
} from '../services/deposit-readiness.js';

const router = Router();

router.post('/wallet/generate', requireUser, (_req, res) =>
  res.status(503).json({
    error:
      'Per-user private-key wallets are not generated by this API. ' +
      'Configure an audited custody provider before accepting deposits.',
  }),
);

router.post('/payment/verify', requireUser, async (req, res, next) => {
  try {
    if (
      !config.liveFundsEnabled ||
      !DEPOSIT_CUSTOMER_INTAKE_READY ||
      !DEPOSIT_CHAIN_VERIFICATION_READY ||
      !DEPOSIT_AUTOMATIC_CREDIT_READY
    ) {
      return res.status(503).json({
        error:
          'Payment verification is disabled until customer intake, chain ' +
          'verification, and duplicate-safe crediting are implemented and reviewed.',
      });
    }

    const {
      txHash,
      recipientAddress,
      expectedAmount,
      tokenType,
    } = req.body || {};

    if (
      !txHash ||
      !recipientAddress ||
      !expectedAmount ||
      !['ETH', 'USDT'].includes(tokenType)
    ) {
      return res.status(400).json({
        error:
          'Transaction hash, recipient, amount, and supported token type are required.',
      });
    }

    const verification = await verifyTransaction(
      txHash,
      recipientAddress,
      expectedAmount,
      tokenType,
    );

    if (!verification.success) {
      return res.status(400).json({ error: verification.message });
    }

    res.json({
      success: true,
      message:
        'Payment was found on the configured network and is queued for protected review.',
    });
  } catch (error) {
    next(error);
  }
});

export default router;
